pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 kink, uint256 slope0, uint256 slope1, address asset) public {
        // valid slope domain
        kink = bound(kink, 1, 1e27 - 1);
        slope0 = bound(slope0, 0, 1e27);
        slope1 = bound(slope1, 0, 1e27);
        vm.assume(asset != address(0));

        // adversarial/counterparty helper: an access control contract that GRANTS access
        GrantAllAC ac = new GrantAllAC();

        // Initialize C through a proxy-context delegatecall (constructor => extcodesize == 0,
        // so the Initializable "construction"/initialSetup path succeeds), then immediately
        // issue an access-checked call (setSlopes) through the same proxy context.
        Proxy p = new Proxy(address(c), address(ac), asset, kink, slope0, slope1);

        bool ok = p.lastCallOk();

        // Rule: with an accessControl that grants access, an access-guarded call must succeed
        // for every admissible input. The mutant never stores accessControl, so checkAccess is
        // made against address(0) and the call reverts for every input.
        assertTrue(ok);
    }
}

contract GrantAllAC {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
}

contract Proxy {
    bool private lastOk;

    constructor(address impl, address ac, address asset, uint256 kink, uint256 s0, uint256 s1) {
        // during construction this contract has no code, so C.initialize's
        // Initializable guard takes the initialSetup branch
        (bool s1, ) = impl.delegatecall(
            abi.encodeWithSelector(C.initialize.selector, ac)
        );
        require(s1, "init failed");

        bytes memory slopes = abi.encode(kink, s0, s1);
        (bool s2, ) = impl.delegatecall(
            abi.encodeWithSelector(C.setSlopes.selector, asset, slopes)
        );
        lastOk = s2;
    }

    function lastCallOk() external view returns (bool) {
        return lastOk;
    }
}

