pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint160 adminSeed) public {
        // Deploy a fresh delegatecall proxy over the implementation so its
        // storage slot for the Initializable marker starts at 0 (the plain
        // `new C()` constructor disables initializers on the direct instance,
        // which is NOT the admissible initialization path).
        Proxy p = new Proxy(address(c));
        address admin = address(adminSeed);

        // First initialize through the proxy: must succeed on both versions.
        (bool ok1, ) = address(p).call(abi.encodeWithSelector(C.initialize.selector, admin));
        assertTrue(ok1, "first initialize must succeed");

        // Second initialize: the reference has latched _initialized = 1, so it
        // must revert; the mutant (latch removed) succeeds again.
        (bool ok2, ) = address(p).call(abi.encodeWithSelector(C.initialize.selector, admin));
        assertTrue(!ok2, "second initialize must revert: initializer is one-shot");
    }
}

contract Proxy {
    address public immutable impl;

    constructor(address _impl) {
        impl = _impl;
    }

    fallback() external payable {
        (bool ok, bytes memory ret) = impl.delegatecall(msg.data);
        if (!ok) {
            assembly {
                revert(add(ret, 32), mload(ret))
            }
        }
        assembly {
            return(add(ret, 32), mload(ret))
        }
    }
}

