pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Proxy p;

    function setUp() public {
        c = new C(); // constructor calls _disableInitializers(), so direct initialize on c always reverts in BOTH versions
        p = new Proxy(address(c)); // delegatecall path sees _initialized == 0, so initialize is reachable
    }

    function testFuzz_property(address accessControl) public {
        vm.assume(accessControl != address(0));
        vm.assume(accessControl != address(p));

        bool ok;
        bytes memory data = abi.encodeWithSelector(c.initialize.selector, accessControl);
        (bool success, ) = address(p).call(data);
        ok = success;

        // Reference: initializer sets _initializing=true, so nested onlyInitializing
        // __Access_init runs and initialize succeeds for EVERY admissible input.
        // Mutant: _initializing is never set, so __Access_init reverts NotInitializing
        // and initialize ALWAYS fails.
        assertTrue(ok, "initialize through proxy should succeed exactly on the reference");
    }
}

contract Proxy {
    bytes32 private constant IMPL_SLOT =
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    constructor(address impl) {
        assembly {
            sstore(IMPL_SLOT, impl)
        }
    }

    fallback() external payable {
        assembly {
            let ptr := mload(0x40)
            calldatacopy(ptr, 0, calldatasize())
            let r := delegatecall(gas(), sload(IMPL_SLOT), ptr, calldatasize(), 0, 0)
            returndatacopy(ptr, 0, returndatasize())
            switch r
            case 0 {
                revert(ptr, returndatasize())
            }
            default {
                return(ptr, returndatasize())
            }
        }
    }
}

